def sum_consecutive_identical_digits(digits: str) -> str:
    stack = []
    for c in digits:
        pending = [c]                  # 待压栈的字符（逆序存放，末尾先处理）
        while pending:
            x = pending.pop()
            if stack and stack[-1] == x:
                stack.pop()
                pending.extend(reversed(str(2 * int(x))))
            else:
                stack.append(x)
    return "".join(stack)


