import java.util.*;

class Solution {
    public String sumConsecutiveIdenticalDigits(String digits) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : digits.toCharArray()) {
            Deque<Character> push = new ArrayDeque<>();
            push.add(c);
            while (!push.isEmpty()) {
                char x = push.poll();
                if (!stack.isEmpty() && stack.peek() == x) {
                    int d = x - '0';
                    stack.pop();
                    String s = String.valueOf(d + d);
                    Deque<Character> tmp = new ArrayDeque<>();
                    for (char ch : s.toCharArray()) tmp.add(ch);
                    while (!push.isEmpty()) tmp.add(push.poll());
                    push = tmp;
                } else {
                    stack.push(x);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = stack.descendingIterator();
        while (it.hasNext()) sb.append(it.next());
        return sb.toString();
    }
}

