        string stack;
        for (char c : digits) {
            deque<char> push; push.push_back(c);
            while (!push.empty()) {
                char x = push.front(); push.pop_front();
                if (!stack.empty() && stack.back() == x) {
                    int d = x - '0';
                    stack.pop_back();
                    string s = to_string(d + d);
                    for (int i = (int)s.size() - 1; i >= 0; i--) push.push_front(s[i]);
                } else {
                    stack += x;
                }
            }
        }
        return stack;
    }
